<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),sweep=ref('half')
const labels=['Core','Support','Growth','Retention']
const values=computed(()=>dataset.value==='A'?[35,48,41,61]:dataset.value==='B'?[42,36,55,48]:dataset.value==='edges'?[0,25,75,100]:[0,0,0,0])
const r=(i:number)=>80-i*17
const start=()=>sweep.value==='half'?180:270
const span=()=>sweep.value==='half'?180:360
function path(v:number,i:number){const radius=r(i),a=start(),end=a+span()*v/100,point=(d:number)=>[160+radius*Math.cos(d*Math.PI/180),115+radius*Math.sin(d*Math.PI/180)],p=point(a),q=point(end);if(v===100&&sweep.value==='full'){const mid=point(a+180);return `M${p} A${radius},${radius} 0 0 1 ${mid} A${radius},${radius} 0 0 1 ${p}`}return `M${p} A${radius},${radius} 0 ${end-a>180?1:0} 1 ${q}`}
function reset(){dataset.value='A';state.value='ready';selected.value=0;sweep.value='half'}
</script>
<template>
<section class="rbusage-demo" aria-label="Local radial bar chart example"><p>Synthetic independent percentages, not shares of one total. Every ring starts at the same angle and uses its own 100% track. Compare fractions, not raw arc lengths across radii.</p><div class="rbusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="edges">Zero and full</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><label>Sweep<select v-model="sweep"><option value="half">Half circle</option><option value="full">Full circle</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><p class="rbusage-legend">Outer to inner: Core, Support, Growth, Retention. {{ sweep==='half'?'0 at left; 100 at right, clockwise over the top.':'0 starts at top; 100 returns to top, clockwise.' }}</p><svg :key="dataset+'-'+sweep" viewBox="0 0 320 235" role="img" aria-label="Four independent radial percentage bars, fixed zero to one hundred per track. Exact values and angles are below."><template v-for="(v,i) in values" :key="i"><path class="rbusage-track" :d="path(100,i)"/><path v-if="v>0" class="rbusage-arc" :class="{selected:selected===i}" :d="path(v,i)" :data-radius="r(i)" :data-value="v"/><circle v-else class="rbusage-zero" :cx="sweep==='half'?160-r(i):160" :cy="sweep==='half'?115:115-r(i)" r="2"/></template><text v-if="sweep==='half'" x="65" y="135">0%</text><text v-if="sweep==='half'" x="244" y="135">100%</text><text v-else x="160" y="20" text-anchor="middle">0 / 100%</text><text x="160" y="220" text-anchor="middle">Equal fractions have different lengths on different radii</text></svg><div role="group" aria-label="Select ring" class="rbusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: {{ values[selected] }}%; {{ (span()*values[selected]/100).toFixed(1) }}° of {{ span() }}°.</p><table class="rbusage-data"><caption>Exact independent percentages, dataset {{ dataset }}</caption><thead><tr><th scope="col">Ring</th><th scope="col">Value</th><th scope="col">Angle</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ values[i] }}%</td><td>{{ (span()*values[i]/100).toFixed(1) }}°</td></tr></tbody></table></template><p v-else role="status" class="rbusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample rings in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.rbusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.rbusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.rbusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.rbusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.rbusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.rbusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.rbusage-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px;font-size:12px}.rbusage-demo svg{display:block;width:100%;height:auto;max-height:330px;margin:16px 0;animation:rbusage-in .2s ease-out}.rbusage-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.rbusage-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.rbusage-pair{opacity:.65}.rbusage-pair.selected{opacity:1}.rbusage-pair.selected text{font-weight:700;fill:var(--vp-c-text-1)}.rbusage-gap{stroke:var(--vp-c-brand-1);stroke-width:2}.rbusage-pair.selected .rbusage-gap{stroke-width:4}.rbusage-primary{fill:var(--vp-c-brand-1);fill-opacity:.18;stroke:var(--vp-c-brand-1);stroke-width:2}.rbusage-reference{fill:none;stroke:var(--vp-c-text-1);stroke-width:2;stroke-dasharray:5 4}.rbusage-dot{fill:var(--vp-c-brand-1)}.rbusage-dot.selected{stroke:var(--vp-c-text-1);stroke-width:2}.rbusage-ring{fill:none;stroke:var(--vp-c-divider);stroke-dasharray:3 3}.rbusage-zero{fill:var(--vp-c-text-1)}.rbusage-choices{display:flex;gap:6px;flex-wrap:wrap}.rbusage-choices button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.rbusage-data{display:table!important;width:100%;font-size:12px}.rbusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.rbusage-data :is(td,th){padding:6px!important}.rbusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes rbusage-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.rbusage-demo svg{animation:none}}
</style>

<style scoped>
.rbusage-track{fill:none;stroke:var(--vp-c-divider);stroke-width:9}.rbusage-arc{fill:none;stroke:var(--vp-c-brand-1);stroke-width:9;stroke-linecap:butt;opacity:.6}.rbusage-arc.selected{opacity:1;stroke:var(--vp-c-text-1);stroke-width:11}.rbusage-zero{fill:var(--vp-c-text-1)}
